import { defineConfig } from "vitest/config";

export default defineConfig({
 test: {
 include: ["tests/**/*.test.ts"],
 environment: "node"
 }
});

import { describe, expect, it } from "vitest";
import { parseEnvText, validateKitEnv } from "../../scripts/validate-env";

describe("env validation", () => {
 it("parses env text into key value pairs", () => {
 const parsed = parseEnvText("KIT_NAME=Demo\nKIT_TIER=STUDIO\n");
 expect(parsed.KIT_NAME).toBe("Demo");
 expect(parsed.KIT_TIER).toBe("STUDIO");
 });

 it("accepts a minimal valid environment", () => {
 const validated = validateKitEnv({
 NEXT_PUBLIC_SUPABASE_URL: "https://example.supabase.co",
 NEXT_PUBLIC_SUPABASE_ANON_KEY: "anon",
 SUPABASE_SERVICE_ROLE_KEY: "service",
 GROQ_API_KEY: "groq",
 EMBEDDING_PROVIDER: "gemini",
 EMBEDDING_MODEL: "text-embedding-004",
 EMBEDDING_DIMENSION: "768",
 KIT_NAME: "Demo",
 KIT_DOMAIN: "general",
 KIT_TIER: "STUDIO",
 KIT_PRIMARY_COLOR: "#01696f"
 });

 expect(validated.KIT_NAME).toBe("Demo");
 expect(validated.KIT_TIER).toBe("STUDIO");
 });
});

import { describe, expect, it } from "vitest";
import {
 buildThemeFromBrandColor,
 exportThemeProfile,
 importThemeProfile,
 resolveThemeProfile,
 themePresets,
 validateThemeAccessibility
} from "../../config/themeEngine";

describe("theme engine", () => {
 it("ships multiple premium presets", () => {
 expect(themePresets.length).toBeGreaterThanOrEqual(5);
 expect(themePresets.map((preset) => preset.id)).toContain("atlas-neutral");
 });

 it("round-trips a brand-derived theme profile through json", () => {
 const profile = buildThemeFromBrandColor("Buyer Theme", "#145f8f", "business");
 const exported = exportThemeProfile(profile);
 const imported = importThemeProfile(exported);

 expect(imported.name).toBe("Buyer Theme");
 expect(imported.tokens.color.accentPrimary).toBe("#145f8f");
 });

 it("validates preset accessibility", () => {
 const presetProfile = resolveThemeProfile({ presetId: "atlas-neutral" });
 const result = validateThemeAccessibility(presetProfile.tokens);

 expect(result.passes).toBe(true);
 expect(result.warnings).toHaveLength(0);
 });
});

import { describe, expect, it } from "vitest";
import {
 buildOnboardingSupportBundle,
 createOnboardingSession,
 executeOnboardingTask,
 getOnboardingTaskGraph
} from "../../api/onboarding";

describe("shared onboarding graph", () => {
 it("loads a shared task graph for web and cli entry modes", () => {
 const graph = getOnboardingTaskGraph();

 expect(graph.version).toBe("1.1.0");
 expect(graph.tasks.length).toBeGreaterThanOrEqual(10);
 expect(graph.tracks.solo[0]).toBe("recommend_segment");
 expect(graph.tracks.business).toContain("stage_corpus_container");
 expect(graph.tracks.business).toContain("review_sources");
 expect(graph.tracks.enterprise).toContain("configure_governance");
 });

 it("creates and advances a cli onboarding session", () => {
 const session = createOnboardingSession({
 entryMode: "cli",
 segment: "business"
 });

 const firstStep = executeOnboardingTask(session, "recommend_segment", {
 teamSize: 6,
 sourceVolume: 120
 });

 expect(firstStep.task.status).toBe("completed");
 expect(firstStep.session.tasks.find((task) => task.taskKey === "create_workspace")?.status).toBe(
 "in_progress"
 );

 const secondStep = executeOnboardingTask(firstStep.session, "create_workspace", {
 workspace_name: "Demo Workspace",
 agent_name: "Demo Agent",
 owner_email: "ops@example.com"
 });

 expect(secondStep.task.output.workspace_status).toBe("ready");
 expect(
 secondStep.session.tasks.find((task) => task.taskKey === "stage_corpus_container")?.status
 ).toBe("in_progress");

 const thirdStep = executeOnboardingTask(secondStep.session, "stage_corpus_container", {
 repository: "demo/repo",
 default_branch: "main",
 corpus_container: ".gsvw/repo-corpus/demo-repo",
 staging_mode: "github_repo"
 });

 expect(thirdStep.task.output.container_status).toBe("ready");
 expect(
 thirdStep.session.tasks.find((task) => task.taskKey === "connect_supabase")?.status
 ).toBe("in_progress");

 const supportBundle = buildOnboardingSupportBundle(thirdStep.session);
 expect(supportBundle.segmentRecommendation).toBe("business");
 expect(supportBundle.nextTask).toBe("connect_supabase");
 });

 it("blocks source review when oversized files are detected", () => {
 const session = createOnboardingSession({
 entryMode: "cli",
 segment: "solo"
 });

 const recommendStep = executeOnboardingTask(session, "recommend_segment", {
 teamSize: 1,
 sourceVolume: 10
 });
 const workspaceStep = executeOnboardingTask(recommendStep.session, "create_workspace", {
 workspace_name: "Demo Workspace",
 agent_name: "Demo Agent"
 });
 const containerStep = executeOnboardingTask(workspaceStep.session, "stage_corpus_container", {
 repository: "demo/repo",
 corpus_container: ".gsvw/repo-corpus/demo-repo"
 });
 const providerStep = executeOnboardingTask(containerStep.session, "connect_provider", {
 provider: "groq",
 model: "llama-3.3-70b-versatile"
 });
 const reviewStep = executeOnboardingTask(providerStep.session, "review_sources", {
 review_mode: "operator-guided",
 source_count: 18,
 batch_count: 2,
 oversized_source_count: 1
 });

 expect(reviewStep.task.status).toBe("blocked");
 expect(reviewStep.task.error?.code).toBe("oversized_sources_detected");
 });
});

import { describe, expect, it } from "vitest";
import { createImportManifestTemplate } from "../../config/importTemplates";
import { handlePacksRoute } from "../../api/packs";

describe("import manifest template", () => {
 it("creates a buyer-owned starter manifest", () => {
 const manifest = createImportManifestTemplate();

 expect(manifest.schemaVersion).toBe("1.1.0");
 expect(manifest.repoContainer).toContain("repo-corpus");
 expect(manifest.entries.length).toBeGreaterThanOrEqual(4);
 expect(manifest.entries[0]?.lane).toBe("knowledge");
 expect(manifest.entries[0]?.sourceUri).toContain("your-document");
 });

 it("rejects manifest route requests without a pack slug", async () => {
 const result = await handlePacksRoute({
 method: "POST",
 action: "manifest"
 });

 expect(result.data).toBeNull();
 expect(result.error?.code).toBe("missing_pack_slug");
 });
});

import { existsSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { mkdtempSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { createRepoCorpusContainer } from "../../scripts/corpusContainer";

describe("repo corpus container", () => {
 it("creates a repo-aware staging scaffold with a manifest and review plan", () => {
 const baseDir = mkdtempSync(join(tmpdir(), "gsvw-repo-corpus-"));

 try {
 const plan = createRepoCorpusContainer({
 repository: "acme/demo-repo",
 defaultBranch: "develop",
 baseDir
 });

 expect(plan.repoSlug).toBe("acme-demo-repo");
 expect(existsSync(plan.manifestPath)).toBe(true);
 expect(existsSync(plan.reviewPath)).toBe(true);
 expect(existsSync(plan.lanePaths.knowledge)).toBe(true);

 const manifest = JSON.parse(readFileSync(plan.manifestPath, "utf8")) as {
 projectName: string;
 owner: string;
 repoContainer: string;
 entries: Array<{ sourceUri: string }>;
 };

 expect(manifest.projectName).toBe("demo-repo");
 expect(manifest.owner).toBe("acme");
 expect(manifest.repoContainer).toBe("..");
 expect(manifest.entries[0]?.sourceUri).toContain("../staged/knowledge/");
 } finally {
 rmSync(baseDir, { recursive: true, force: true });
 }
 });
});

import { describe, expect, it } from "vitest";
import { createWorkspaceScaffold, getWorkspaceReadiness, previewWorkspaceTheme } from "../../api/workspaces";

describe("workspace helpers", () => {
 it("creates a workspace scaffold with entitlements and theme profile", () => {
 const workspace = createWorkspaceScaffold({
 id: "workspace-1",
 organizationId: "org-1",
 name: "Demo Workspace",
 slug: "demo-workspace",
 tier: "STUDIO",
 segment: "business",
 themePresetId: "lagoon-glass"
 });

 expect(workspace.entitlements.segment).toBe("business");
 expect(workspace.themeProfile.name).toBe("Lagoon Glass");
 });

 it("scores workspace readiness across all lanes", () => {
 const readiness = getWorkspaceReadiness(
 [
 {
 lane: "knowledge",
 sourceCount: 25,
 sourceFreshness: 80,
 sourceDiversity: 80,
 evaluationPassRate: 84,
 citationCoverage: 78,
 operatorSatisfaction: 88
 },
 {
 lane: "code",
 sourceCount: 20,
 sourceFreshness: 70,
 sourceDiversity: 64,
 evaluationPassRate: 72,
 citationCoverage: 68,
 operatorSatisfaction: 74
 },
 {
 lane: "product",
 sourceCount: 18,
 sourceFreshness: 74,
 sourceDiversity: 62,
 evaluationPassRate: 71,
 citationCoverage: 67,
 operatorSatisfaction: 76
 },
 {
 lane: "context",
 sourceCount: 24,
 sourceFreshness: 86,
 sourceDiversity: 78,
 evaluationPassRate: 82,
 citationCoverage: 73,
 operatorSatisfaction: 90
 }
 ],
 [
 {
 label: "Workspace created",
 completed: true,
 detail: "done"
 },
 {
 label: "Eval suite run",
 completed: true,
 detail: "done"
 }
 ]
 );

 expect(readiness.error).toBeNull();
 expect(readiness.data?.overallScore).toBeGreaterThan(70);
 expect(readiness.data?.goLiveVerdict).toBe("ready");
 });

 it("previews a workspace theme preset", () => {
 const preview = previewWorkspaceTheme("signal-noir");
 expect(preview.data?.name).toBe("Signal Noir");
 });
});

import { describe, expect, it } from "vitest";
import {
 buildStarterPackRouteRequest,
 buildImportManifestForPack,
 buildStarterPackPlan,
 handlePacksRoute,
 listSourceBundles,
 previewStarterPacks
} from "../../api/packs";

describe("starter packs", () => {
 it("returns preview metadata for pack application", () => {
 const previews = previewStarterPacks();
 const devopsPack = previews.find((pack) => pack.slug === "devops-terminal-pack");

 expect(devopsPack).toBeDefined();
 expect(devopsPack?.recommendedSourceBundles).toContain("code-context-bundle");
 expect(devopsPack?.generatedMemoryKeys).toContain("operator_prefers_cli");
 });

 it("lists source bundles by lane", () => {
 const bundles = listSourceBundles();
 expect(bundles.some((bundle) => bundle.lane === "context")).toBe(true);
 expect(bundles.some((bundle) => bundle.slug === "code-context-bundle")).toBe(true);
 });

 it("builds an activation plan from a starter pack", () => {
 const result = buildStarterPackPlan("devops-terminal-pack");

 expect(result.error).toBeNull();
 expect(result.data?.selectedSourceBundles).toContain("code-context-bundle");
 expect(result.data?.generatedMemoryKeys).toContain("operator_prefers_cli");
 });

 it("builds an import manifest from the selected pack plan", () => {
 const result = buildImportManifestForPack(
 "general-operator-foundation",
 "demo-project",
 "demo-owner"
 );

 expect(result.error).toBeNull();
 expect(result.data?.projectName).toBe("demo-project");
 expect(result.data?.entries.length).toBeGreaterThan(0);
 });

 it("exposes a route-style pack adapter", async () => {
 const result = await handlePacksRoute({
 method: "POST",
 action: "manifest",
 packSlug: "agent-source-starter-bundle",
 projectName: "buyer-project",
 owner: "buyer-owner"
 });

 expect(result.error).toBeNull();
 expect("entries" in (result.data ?? {})).toBe(true);
 });

 it("builds a route request for pack application", () => {
 const request = buildStarterPackRouteRequest({
 userId: "user-1",
 packSlug: "general-operator-foundation",
 projectName: "buyer-project",
 owner: "buyer-owner",
 selectedBundleSlugs: ["knowledge-core-bundle"]
 });

 expect(request.action).toBe("apply");
 expect(request.userId).toBe("user-1");
 expect(request.selectedBundleSlugs).toContain("knowledge-core-bundle");
 });

 it("requires env-backed handling for apply route preview", async () => {
 const result = await handlePacksRoute({
 method: "POST",
 action: "apply",
 userId: "user-1",
 packSlug: "general-operator-foundation"
 });

 expect(result.data).toBeNull();
 expect(result.error?.code).toBe("env_required_for_apply");
 });
});

import { describe, expect, it } from "vitest";
import { buildMemoryInsert } from "../../api/memory";

describe("memory helpers", () => {
 it("applies a default importance score", () => {
 const insert = buildMemoryInsert({
 userId: "user-1",
 sessionId: "session-1",
 key: "tone",
 value: {
