#!/usr/bin/env python3
"""Generic corpus ingest scaffold for buyer-owned repositories.

Reads a manifest JSON file, chunks source text, optionally embeds chunks,
and inserts rows into Supabase `knowledge_fragments`.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
import textwrap
import urllib.request
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable

VALID_LANES = {"knowledge", "code", "product", "context"}


@dataclass
class ManifestEntry:
 title: str
 lane: str
 source_type: str
 source_uri: str
 notes: str


def _load_json(path: Path) -> dict:
 return json.loads(path.read_text(encoding="utf-8"))


def _chunk_text(text: str, chunk_size: int, overlap: int) -> list[str]:
 words = text.split()
 if not words:
 return []

 stride = max(1, chunk_size - overlap)
 chunks: list[str] = []
 for i in range(0, len(words), stride):
 segment = words[i : i + chunk_size]
 if not segment:
 continue
 chunks.append(" ".join(segment).strip())
 if i + chunk_size >= len(words):
 break
 return chunks


def _read_source(entry: ManifestEntry, manifest_dir: Path) -> str:
 if entry.source_type == "text":
 return entry.source_uri

 if entry.source_type == "file":
 source_path = (manifest_dir / entry.source_uri).resolve()
 return source_path.read_text(encoding="utf-8")

 if entry.source_type == "url":
 with urllib.request.urlopen(entry.source_uri) as response: # nosec B310
 raw = response.read().decode("utf-8", errors="ignore")
 return re.sub(r"<[^>]+>", " ", raw)

 raise ValueError(f"Unsupported sourceType: {entry.source_type}")


def _embed_openai(text: str, model: str, api_key: str) -> list[float]:
 payload = json.dumps({"input": text, "model": model}).encode("utf-8")
 request = urllib.request.Request(
 url="https://api.openai.com/v1/embeddings",
 data=payload,
 headers={
 "Content-Type": "application/json",
 "Authorization": f"Bearer {api_key}",
 },
 method="POST",
 )
 with urllib.request.urlopen(request) as response: # nosec B310
 data = json.loads(response.read().decode("utf-8"))
 return data["data"][0]["embedding"]


def _build_fragment_payload(
 entries: Iterable[ManifestEntry],
 manifest_dir: Path,
 user_id: str,
 chunk_size: int,
 chunk_overlap: int,
 embedding_provider: str,
 embedding_model: str,
 openai_api_key: str | None,
) -> list[dict]:
 fragments: list[dict] = []

 for entry in entries:
 source_text = _read_source(entry, manifest_dir)
 chunks = _chunk_text(source_text, chunk_size=chunk_size, overlap=chunk_overlap)
 for chunk_index, chunk in enumerate(chunks):
 embedding = None
 if embedding_provider == "openai":
 if not openai_api_key:
 raise ValueError("OPENAI_API_KEY is required when embedding-provider=openai")
 embedding = _embed_openai(chunk, embedding_model, openai_api_key)

 fragments.append(
 {
 "user_id": user_id,
 "namespace": entry.lane,
 "title": entry.title,
 "content": chunk,
 "source_uri": entry.source_uri,
 "source_type": entry.source_type,
 "chunk_index": chunk_index,
 "metadata": {
 "notes": entry.notes,
 "ingest_scaffold": "gv_operator_kit/scripts/corpus_ingest.py",
 },
 "embedding": embedding,
 }
 )

 return fragments


def _insert_supabase_rows(url: str, service_role_key: str, rows: list[dict]) -> None:
 endpoint = f"{url.rstrip('/')}/rest/v1/knowledge_fragments"
 encoded = json.dumps(rows).encode("utf-8")
 request = urllib.request.Request(
 endpoint,
 data=encoded,
 headers={
 "Content-Type": "application/json",
 "apikey": service_role_key,
 "Authorization": f"Bearer {service_role_key}",
 "Prefer": "return=minimal",
 },
 method="POST",
 )

 with urllib.request.urlopen(request) as response: # nosec B310
 if response.status >= 300:
 raise RuntimeError(f"Supabase insert failed: HTTP {response.status}")


def _parse_entries(manifest: dict) -> list[ManifestEntry]:
 parsed: list[ManifestEntry] = []
 for raw in manifest.get("entries", []):
 lane = raw.get("lane", "knowledge")
 if lane not in VALID_LANES:
 raise ValueError(f"Unsupported lane '{lane}'. Expected one of {sorted(VALID_LANES)}")

 parsed.append(
 ManifestEntry(
 title=raw["title"],
 lane=lane,
 source_type=raw["sourceType"],
 source_uri=raw["sourceUri"],
 notes=raw.get("notes", ""),
 )
 )
 return parsed


def build_parser() -> argparse.ArgumentParser:
 parser = argparse.ArgumentParser(
 description="Ingest buyer-owned corpus from a manifest into Supabase knowledge_fragments."
 )
 parser.add_argument("manifest", help="Path to import manifest JSON file")
 parser.add_argument("--user-id", required=True, help="kit_users.id target for inserted fragments")
 parser.add_argument("--supabase-url", default=os.getenv("NEXT_PUBLIC_SUPABASE_URL", ""))
 parser.add_argument("--service-role-key", default=os.getenv("SUPABASE_SERVICE_ROLE_KEY", ""))
 parser.add_argument(
 "--embedding-provider",
 choices=["none", "openai"],
 default=os.getenv("EMBEDDING_PROVIDER", "none").lower() or "none",
 )
 parser.add_argument(
 "--embedding-model",
 default=os.getenv("EMBEDDING_MODEL", "text-embedding-3-small"),
 )
 parser.add_argument("--chunk-size", type=int, default=350)
 parser.add_argument("--chunk-overlap", type=int, default=60)
 parser.add_argument("--dry-run", action="store_true", help="Print summary only, no inserts")
 return parser


def main() -> int:
 parser = build_parser()
 args = parser.parse_args()

 if not args.supabase_url or not args.service_role_key:
 parser.error("Missing Supabase credentials. Set --supabase-url and --service-role-key or env vars.")

 manifest_path = Path(args.manifest).resolve()
 manifest = _load_json(manifest_path)
 entries = _parse_entries(manifest)

 openai_api_key = os.getenv("OPENAI_API_KEY")
 rows = _build_fragment_payload(
 entries=entries,
 manifest_dir=manifest_path.parent,
 user_id=args.user_id,
 chunk_size=args.chunk_size,
 chunk_overlap=args.chunk_overlap,
 embedding_provider=args.embedding_provider,
 embedding_model=args.embedding_model,
 openai_api_key=openai_api_key,
 )

 by_lane: dict[str, int] = {}
 for row in rows:
 lane = row["namespace"]
 by_lane[lane] = by_lane.get(lane, 0) + 1

 summary = textwrap.dedent(
 f"""
 Manifest: {manifest_path}
 Entries: {len(entries)}
 Chunks: {len(rows)}
 Lanes: {json.dumps(by_lane, sort_keys=True)}
 Embeddings: {args.embedding_provider}
 Dry run: {args.dry_run}
 """
 ).strip()
 print(summary)

 if args.dry_run:
 return 0

 _insert_supabase_rows(
 url=args.supabase_url,
 service_role_key=args.service_role_key,
 rows=rows,
 )
 print("Ingest complete.")
 return 0


if __name__ == "__main__":
 try:
 raise SystemExit(main())
 except Exception as exc:
 print(f"ERROR: {exc}", file=sys.stderr)
 raise

import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import {
 corpusContainerBlueprint,
 corpusReviewChecklist,
 type CorpusLane
} from "../config/trainerBlueprint";
import { createImportManifestTemplate } from "../config/importTemplates";

export interface RepoCorpusContainerInput {
 repository: string;
 defaultBranch?: string;
 baseDir?: string;
}

export interface RepoCorpusContainerPlan {
 repository: string;
 owner: string;
 name: string;
 repoSlug: string;
 defaultBranch: string;
 containerRoot: string;
 manifestPath: string;
 reviewPath: string;
 readmePath: string;
 directories: string[];
 lanePaths: Record<CorpusLane, string>;
}

function slugify(value: string): string {
 return value
 .trim()
 .toLowerCase()
 .replace(/[^a-z0-9]+/g, "-")
 .replace(/^-+|-+$/g, "");
}

function parseRepository(repository: string): { owner: string; name: string } {
 const cleaned = repository.trim().replace(/^https?:\/\/github\.com\//, "").replace(/\.git$/, "");
 const [owner, name] = cleaned.split("/").filter(Boolean);

 if (!owner || !name) {
 throw new Error("Repository must look like owner/repo or a GitHub URL.");
 }

 return { owner, name };
}

export function buildRepoCorpusContainerPlan(
 input: RepoCorpusContainerInput
): RepoCorpusContainerPlan {
 const parsedRepository = parseRepository(input.repository);
 const repoSlug = slugify(`${parsedRepository.owner}-${parsedRepository.name}`);
 const baseDir = resolve(input.baseDir ?? ".gsvw", "repo-corpus");
 const containerRoot = resolve(baseDir, repoSlug);
 const directories = corpusContainerBlueprint.map((zone) => resolve(containerRoot, zone.path));

 return {
 repository: input.repository,
 owner: parsedRepository.owner,
 name: parsedRepository.name,
 repoSlug,
 defaultBranch: input.defaultBranch?.trim() || "main",
 containerRoot,
 manifestPath: resolve(containerRoot, "manifests", "import-manifest.template.json"),
 reviewPath: resolve(containerRoot, "review", "seed-plan.md"),
 readmePath: resolve(containerRoot, "README.md"),
 directories,
 lanePaths: {
 knowledge: resolve(containerRoot, "staged", "knowledge"),
 code: resolve(containerRoot, "staged", "code"),
 product: resolve(containerRoot, "staged", "product"),
 context: resolve(containerRoot, "staged", "context")
 }
 };
}

function buildReadme(plan: RepoCorpusContainerPlan): string {
 const zones = corpusContainerBlueprint
 .map((zone) => `- \`${zone.path}\`: ${zone.summary}`)
 .join("\n");
 const checklist = corpusReviewChecklist.map((item, index) => `${index + 1}. ${item}`).join("\n");

 return `# Repo Corpus Container

Repository: \`${plan.owner}/${plan.name}\`
Default branch: \`${plan.defaultBranch}\`

This scaffold keeps raw repo exports separate from staged corpus lanes so the first import run stays small, auditable, and understandable.

## Zones

${zones}

## First pass

${checklist}

## Suggested first batch

- Add repo exports to \`incoming/github\`
- Add buyer docs to \`incoming/files\`
- Move only the highest-signal files into \`staged/knowledge\`, \`staged/code\`, \`staged/product\`, or \`staged/context\`
- Edit \`manifests/import-manifest.template.json\`
- Run a dry ingest before any live write
`;
}

function buildSeedPlan(plan: RepoCorpusContainerPlan): string {
 return `# Seed Plan

Repository: ${plan.owner}/${plan.name}
Default branch: ${plan.defaultBranch}

## Review sequence

1. Export or collect repo docs into ../incoming/github
2. Move product and operational files into the staged lane folders
3. Keep the first batch under 15 sources
4. Generate or edit ../manifests/import-manifest.template.json
5. Run the ingest in dry-run mode first

## Notes

- Flag anything oversized, duplicated, or obviously corrupted before import.
- Keep product docs out of the code lane unless they explain implementation behavior.
- If a source does not clearly fit a lane, hold it in review until the operator decides.
`;
}

export function createRepoCorpusContainer(
 input: RepoCorpusContainerInput
): RepoCorpusContainerPlan {
 const plan = buildRepoCorpusContainerPlan(input);

 mkdirSync(plan.containerRoot, { recursive: true });
 for (const directory of plan.directories) {
 mkdirSync(directory, { recursive: true });
 }

 const manifest = createImportManifestTemplate();
 manifest.projectName = plan.name;
 manifest.owner = plan.owner;
 manifest.repoContainer = "..";
 manifest.entries = manifest.entries.map((entry) => ({
 ...entry,
 sourceUri: entry.sourceUri.replace("./", "../")
 }));

 writeFileSync(plan.readmePath, buildReadme(plan), "utf8");
 writeFileSync(plan.reviewPath, buildSeedPlan(plan), "utf8");
 writeFileSync(plan.manifestPath, JSON.stringify(manifest, null, 2) + "\n", "utf8");

 return plan;
}

